import{z as d,x as B,o as t,c as A,q as i,j as E,D as r,d as n,s as o,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"默认配置加固","description":"","frontmatter":{"title":"默认配置加固","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/default-config-hardening.md","filePath":"cs/default-config-hardening.md","lastUpdated":1791413859000}'),p={name:"cs/default-config-hardening.md"};function h(m,a,f,c,S,u){const l=B("Mermaid");return t(),A("div",null,[a[2]||(a[2]=i('<h1 id="默认配置加固" tabindex="-1">默认配置加固 <a class="header-anchor" href="#默认配置加固" aria-label="Permalink to &quot;默认配置加固&quot;">​</a></h1><div class="epigraph"><p>出厂默认口令、开放管理口、示例虚拟主机，是扫描后最便宜的入口。加固基线把「开箱可用」收成「开箱最小」。</p><footer>—— 据 CIS Benchmarks 的基线思想；NIST SP 800-123；对照 Anderson 对默认</footer></div><p>上一课<a href="/cs/network-segmentation">分段</a>假定段内主机不是默认口令。缺口是<strong>主机与中间件默认</strong>。本课讲基线，不写利用默认口令的步骤。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>设备管理界面默认账户、数据库空口令、目录列表、框架示例应用（Tomcat manager、调试端点）、数据库监听全网卡。这类入口不需要漏洞：扫描器枚举出厂组合即可登录。Mirai 2016 用约六十组默认口令扫出僵尸网络，把「出厂状态是敌意初始条件」变成可测量的经济损失。缺口是黄金镜像、配置即代码、关闭示例。</p><p><span class="marginnote">数字实例：Mirai 只靠约 60 组出厂用户名口令组合，就扫出几十万设备的僵尸网络，2016 年打瘫了半个美国东海岸的 DNS 服务。攻击者没碰任何漏洞——60 组组合，每台设备一次登录尝试就够。</span></p><h3 id="云安全组" tabindex="-1">云安全组 <a class="header-anchor" href="#云安全组" aria-label="Permalink to &quot;云安全组&quot;">​</a></h3><p>默认 0.0.0.0/0 是分段失败：把上一课的段界换成一份全 allow 的清单。安全组要默认 deny、按端口收来源：SSH 22、RDP 3389、数据库 3306/5432/6379 只对跳板段开放。</p><p><span class="marginnote">术语翻译：fail-safe default（失败安全默认）是 Saltzer-Schroeder 安全原则之一——系统在「没人显式允许」时的状态应当是拒绝而非放行。落到配置上：安全组默认 deny、监听默认关、示例默认下线，每一条放行都要有理由、有记录、有有效期。</span></p><p><span class="marginnote">CIS。禁止默认口令利用教程。SIEM 下一课把加固后的日志收走。Redis/MongoDB 曾因默认无鉴权引发勒索潮；Redis 之后默认 protected-mode 只听回环。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照 CIS/STIG 清单作过程，不是一次勾选：条目进黄金镜像构建管线，新主机出厂即最小；配置即代码把偏离变成版本差异可审。运行态仍会漂移——补丁、临时放行、手工排障——所以基线要配漂移检测闭环。改默认口令只是第一行：关掉不用的监听、详细错误转通用错误、示例与文档端点下线；基线条目的手工豁免要带有效期，到期自动失效。下一课 SIEM 与日志。</p>',13)),(t(),E(s,null,{default:r(()=>[o(l,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20DEF%5B%22%E5%87%BA%E5%8E%82%E9%BB%98%E8%AE%A4%22%5D%20--%3E%20ATT%5B%22%E6%89%AB%E6%8F%8F%E5%8D%B3%E4%B8%AD%22%5D%0A%20%20BASE%5B%22%E5%9F%BA%E7%BA%BF%E9%95%9C%E5%83%8F%22%5D%20--%3E%20MIN%5B%22%E6%9C%80%E5%B0%8F%E6%9C%8D%E5%8A%A1%E4%B8%8E%E5%8F%A3%E4%BB%A4%E7%AD%96%E7%95%A5%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[n("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"出厂默认面向「开箱即用」：可用性最优、安全最差；基线把默认值翻成 fail-safe default（Saltzer-Schroeder 原则之一），加固是把它工程化，不是一次性动作。失败模式：基线只做一次，新版本带进新默认；豁免与临时放行无记录，漂移从此不可见；改端口只减扫描噪声，不减攻击面。攻击面来自忘记改的合同。日志下一课让改没改可被看见。",-1)),a[5]||(a[5]=e("p",null,[e("span",{class:"marginnote"},"常见误区：初学者容易以为「把管理端口改成 8022」就算加固。改端口只滤掉最懒的扫描噪声，端口扫描器照样枚举全部 65535 个端口；真正的攻击面来自没改的口令、没关的监听、没下线的示例——是「忘了改的合同」，不是端口号。")],-1)),(t(),E(s,null,{default:r(()=>[o(l,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20BASE%5B%22%E9%BB%84%E9%87%91%E9%95%9C%E5%83%8F%EF%BC%9A%E5%87%BA%E5%8E%82%E5%8D%B3%E5%9F%BA%E7%BA%BF%22%5D%20--%3E%20RUN%5B%22%E8%BF%90%E8%A1%8C%E6%80%81%E4%B8%BB%E6%9C%BA%22%5D%0A%20%20RUN%20--%3E%20DR%5B%22%E6%BC%82%E7%A7%BB%E6%A3%80%E6%B5%8B%EF%BC%9A%E9%80%90%E6%9D%A1%E5%AF%B9%E6%AF%94%E5%9F%BA%E7%BA%BF%22%5D%0A%20%20DR%20--%3E%20OK%5B%22%E4%B8%80%E8%87%B4%EF%BC%9A%E4%BF%9D%E6%8C%81%22%5D%0A%20%20DR%20--%3E%20DIFF%5B%22%E5%81%8F%E7%A6%BB%EF%BC%9A%E7%99%BB%E8%AE%B0%E8%B1%81%E5%85%8D%E6%88%96%E5%9B%9E%E6%BB%9A%22%5D%0A%20%20DIFF%20--%3E%20BASE%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=i('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写对默认管理口的利用。出厂状态要当成敌意的初始条件；基线是过程，不替代<a href="/cs/patch-management">补丁管理</a>。SIEM 下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>分段挡跨区；默认口令在段内仍开大门。</li><li>基线镜像与配置即代码。</li><li>云安全组默认全开等于无分段。</li><li>下一课 SIEM。</li><li>出处：CIS Benchmarks；NIST SP 800-123；Anderson。</li></ul>',4))])}const g=d(p,[["render",h]]);export{F as __pageData,g as default};
